import re, os

OUT = "."

def nav_link(href, label, current):
    active = href == current
    cls = "px-3 py-2 text-sm font-body font-medium rounded-md transition-colors " + (
        "text-primary bg-primary/5" if active else
        "text-muted-foreground hover:text-primary hover:bg-primary/5"
    )
    return f'<a class="{cls}" href="{href}">{label}</a>'

