def clean(html):
    # remove framer-motion initial-state inline styles so content is visible without JS
    html = re.sub(r'\s*style="opacity:\s*0[^"]*"', '', html)
    html = re.sub(r'\s*style="transform:[^"]*"', '', html)
    # fix internal links
    html = html.replace('href="/"', 'href="index.html"')
    html = html.replace('href="/history"', 'href="history.html"')
    html = html.replace('href="/parish-life"', 'href="parish-life.html"')
    html = html.replace('href="/jubilee"', 'href="jubilee.html"')
    html = html.replace('href="/devotion"', 'href="devotion.html"')
    html = html.replace('href="/contact"', 'href="contact.html"')
    # fix image sources to local assets
    html = html.replace('https://media.base44.com/images/public/69f2177f78178e1e25d398d1/d41b9bcb7_logo.png', 'assets/images/logo.png')
    html = html.replace('https://media.base44.com/images/public/user_68e0bdca615f6152b045e3d7/a222922c1_ayroorchurch.jpg', 'assets/images/hero-church.jpg')
    html = html.replace('https://media.base44.com/images/public/user_68e0bdca615f6152b045e3d7/f80dfadad_stantonttransparent.png', 'assets/images/st-antony.png')
    html = html.replace('https://media.base44.com/images/public/user_68e0bdca615f6152b045e3d7/424f55d4e_SnapInstato_46225361_334448004010470_2610752943758170576_n.jpg', 'assets/images/altar.jpg')
    html = html.replace('https://media.base44.com/images/public/user_68e0bdca615f6152b045e3d7/fd133fec1__ayroor_church.png', 'assets/images/church-bg.png')
    return html

def page(title, current, main_html, desc):
    main_html = clean(main_html)
    return f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title} | St. Antony's Church Ayroor</title>
<meta name="description" content="{desc}">
<link rel="icon" type="image/png" href="assets/images/logo.png">
<link rel="stylesheet" href="assets/site.css">
</head>
<body class="min-h-screen flex flex-col">
{header(current)}
<main class="flex-1">
{main_html}
</main>
{FOOTER}
<script src="assets/common.js"></script>
</body>
</html>
'''

